function balanced(s) {
  const st = []
  const opener = { ')': '(', ']': '[', '}': '{' }
  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') {
      st.push(ch)
    } else {
      if (st.length === 0) return false
      if (st.pop() !== opener[ch]) return false
    }
  }
  return st.length === 0
}

